; kea128_gen.asm - GENERATED by tools/make128.py from kea48.asm - DO NOT EDIT (anchors: A1 start, A5 game track, A4 load_level, A2 isr, A3 shim include, A3 beeper removed)
; kea48.asm - Kill'em All, 48K edition. Milestone M1.1: back-buffered flicker-free textured raycaster, OR-only unrolled bands.
; Build: tools/build48.sh  (gen48.py -> gen/*.asm, mapc.py -> gen/level48.bin, pasmo --tapbas)
; Fixed point: positions 8.8 (cell.frac), angles 256/turn (0 = east, 64 = south), vectors s8.8.
; Window (M2.5C): 192x96 pixels at x 32..223, y 8..103 (byte columns 4..27, attribute rows 1..12). 64 rays, 3 px each
; (byte-rounded widths 3,3,2,4,4,2,3,3 per 24-px group: bytecol = 3*(col>>3) + ADJTAB[col&7], slot bits SLOTM[col&7]).
; Rendering: all pixels go to the back buffer BUF (column-major, 24 byte-columns x 96-byte stride) and are copied to the
; screen in one burst (COPYBUF) at the end of render. M2.5: the window has ONE ink (0x07, set by cls) - walls, floor,
; ceiling and sprites are all white on black, so no attribute cell can ever clash (Zosya/TTT style); the HUD keeps its colours.
        org 32768

ISRVEC  equ 65021          ; IM2 vector target (table of 253 at 65024..65280)
TABLE   equ 65024
        IF DEFINED FLIP
ATTRWIN equ 24832+0x24     ; lane F: staging window in BUF (same low bytes 24h..3Bh per row, stride 32; shim128.asm fl_ca)
        ELSE
ATTRWIN equ 22564          ; attribute address of window row 0 (attr row 1), column 4 (M2.5C: 24 cells per row)
        ENDIF
CHJ     equ 24576          ; M2.5C: 0x6000..0x60C1 RAM: CHJ[n] = SCHAIN_END - 5n (n 0..96), built by init_game (sprites_f.asm
                           ; reads it with ld l,a / inc l: page-contained). 0x60C2..0x60FF: ISR pushes at the last push of
                           ; CLRBUF (SP = BUF) land here, not in SOLIDPG (latent M2.2..M2.5B bug: 4 B / 128K ~36 B per hit).
BUF     equ 24832          ; 0x6100: back buffer, byte column c (0..23), row r at COLBASE[c] + r = BUF + c*96 + r (2,304 B)
BUFCOLS equ 24             ; (tests read these two)
BUFSTR  equ 96
FTX     equ 27136          ; 0x6A00: per-frame table, word FTX + 2k = fracx * k (k = 0..255), rebuilt when fracx changes
                           ; (ISR pushes at the end of its build land in BUF, which CLRBUF rewrites right after)
FTY     equ 27904          ; 0x6D00: same for fracy (page 0x6C holds dash_data + the landing reserve for this build)
ROMFONT equ 15616
SOLIDPG equ 0x5F               ; M2.2: RAM page 0x5F00..0x5FFF (dead BASIC area above DRAM_END, see state.asm) filled with
                               ; 0xFF by init_game = solid texture page. RAM, not ROM: the +2/+3 ROM 1 has no all-FF page.
FAR_H   equ 16                 ; walls this high or lower are drawn solid (distance >= 6 cells)
        IF DEFINED FLIP
; lane F (6 Nov 2026, 128K only, pasmo --equ FLIP=1): shadow-screen flip (shim128.asm rules F1..F7). The stack moves
; into the fixed 16 KB (never paged): FSTACK 5D00h grows down over 5C00h..5CFFh (48K system variables: dead here, the
; ROM is never entered; measured depth 16 B + ISR, build/m25_stack.out) so SP never points into a paged bank (rule F2).
; The IM2 table + ISRVEC stay at TABLE/ISRVEC in bank 0 AND are mirrored into bank 7 (fl_init), so an interrupt during
; a bank-7 phase reaches isr. ATTRWIN (attr_write's / wt_fill's 12 x 24 window, stride 32) becomes a STAGING window in
; BUF (dead after COPYBUF): fl_ca copies the 288 cells into the hidden screen with bank 7 paged (rule F4).
FSTACK  equ 5D00h
        ENDIF
start:  call bank_init         ; T4 128K anchor A1
        di
        IF DEFINED FLIP
        ld sp,FSTACK
        ELSE
        ld sp,65008
        ENDIF
        ld hl,TABLE
        ld de,TABLE+1
        ld bc,256
        ld (hl),253
        ldir
        ld a,195
        ld (ISRVEC),a
        ld hl,isr
        ld (ISRVEC+1),hl
        IF DEFINED FLIP
        call fl_init           ; same table + vector into bank 7 (rule F2); bank 0 paged again on return
        ENDIF
        ld a,254
        ld i,a
        im 2
        ei
        IF DEFINED FLIP
        ELSE
        ld a,2
        ld (mt_outer),a        ; T3 knob: real 2-voice menu tune (the menu frame has the CPU)
        ENDIF
menu:
        IF DEFINED FLIP
        ld sp,FSTACK           ; reached by jp from deep inside the game (level_clear): fresh stack (fixed area, rule F2)
        call fl_show0          ; rule F7: screen 0 displayed before the front end draws into it
        ELSE
        ld sp,65008            ; reached by jp from deep inside the game (level_clear): fresh stack
        ENDIF
        ld a,1
        call snd_music         ; menu tune on (honours opt_music)
        call fe_run            ; T2 menu over the title screen; returns when START is chosen
        ld a,2                 ; T4 128K anchor A5: AY game track instead of stop
        call snd_music
        call cls               ; black screen, white ink
        call new_game
        call apply_opts
        call hud_init
main:   ld hl,(frames)
        inc hl
        ld (frames),hl
        IF DEFINED GLIDE
        call glide_render      ; M2.9b (128K/Next): glide_in, render, glide_out (game_d.asm) - same 3 B as call render
        ELSE
        call render
        ENDIF
        IF DEFINED MOUSE
        call mouse_look        ; lane M (5 Nov 2026, 128K/Next: pasmo --equ MOUSE=1): mouse look once per rendered frame (input.asm)
        ENDIF
        call steps             ; M2.9 (4 Nov 2026): fixed-rate game logic, 10 steps/s on every machine (below)
        ld a,(in_break)
        or a
        jp z,main
        IF DEFINED FLIP
        call fl_show0          ; rule F7: the pause menu draws into screen 0 - show it first
        ENDIF
        call fe_pause          ; BREAK: pause menu over rows 16..23; A = 0 resume, 1 quit to menu
        or a
        jr z,resume
menu2:  call menu_bg
        jp menu
resume:
        call apply_opts
        call hud_redraw        ; the menu used rows 16..23: restore the HUD
        jp main

; M2.9 steps (tools/m29_edit_steps.py, 4 Nov 2026): fixed time step. game_tick runs once per STEP ticks of the 50 Hz counter
; (0.1 s) since the last step, whatever the frame rate: faster than a step (Next @ 28 MHz) -> halt until the next interrupt
; (the picture would not change anyway: display capped at 10 frames/s); slower -> up to 2 steps per frame, the rest of a
; backlog (pause menu, tape load, YOU DIED wait) is dropped so the game never bursts. step_t = low byte of ticks at the last
; step: the 8-bit difference is exact below 5.1 s and anything longer is capped to 2 steps anyway. Always runs >= 1 step,
; so in_break (read by game_tick's in_read) is fresh for the caller. 47 B. Interrupts must be on (they are in main).
STEP    equ 5                  ; ticks per game step = 10 steps/s; the only speed knob (movement 0.15 cell/step = 1.5 cells/s)
steps:  ld a,(ticks)
        ld hl,step_t
        sub (hl)               ; A = ticks elapsed since the last step (mod 256)
        cp 3*STEP
        jr c,st_ok
        ld a,(ticks)           ; backlog >= 3 steps (stall): forget it, keep exactly 2 (a 0..4 tick remainder is kept)
        sub 2*STEP
        ld (hl),a
        ld a,2*STEP
st_ok:  cp STEP
        jp nc,st_two           ; >= 1 step due: game_d.asm st_two (split: code before COLBASE has only 7 B page slack)
        IF DEFINED GLIDE
        ret                    ; M2.9b: no step due -> draw another frame (the camera glides); 128K/Next only
        ELSE
        halt                   ; too early for a step: wait for the next 50 Hz interrupt (isr: ticks + 1), then look again
        jr steps
        ENDIF
step_t: defb 0

; ---------------------------------------------------------------- T6: game start, options, pause HUD restore, tape levels
new_game:                      ; stats reset + level 1 (resident copy restored from tape only if a later level overwrote it)
        ld a,100
        ld (health),a
        ld a,50
        ld (ammo),a
        xor a
        ld (keys),a
        ld (kills),a
        ld (level),a
        ld (shield),a          ; M2.2
        ld (door_cool),a
        call doors_restore
        ld a,(level_data)
        cp 1
        jr z,ng1
        ld a,1
        call load_level        ; level 1 was overwritten by level 2/3: fetch it again from tape
ng1:    jp init_game
; M2.6: apply_opts lives in ../common/floor.asm now (six CLRBUF fill words: D5 ceiling DE'/BC'/IX/IY + floor DE/BC)
hud_redraw:
        call fe_clr_bottom     ; the menu used pixel rows 128..191 / attr rows 16..23
        call clr_rows13        ; rows 13..15 (rail, labels) are redrawn by hud_init
        jp hud_init
clr_rows13:                    ; pixel rows 104..127 (text rows 13..15) = 0
        ld hl,0x48A0
        ld a,8
cr13:   push hl
        ld d,h
        ld e,l
        inc de
        ld (hl),0
        ld bc,95
        ldir
        pop hl
        inc h
        dec a
        jr nz,cr13
        ret
menu_bg:                       ; back from the game: the frozen 3D view stays, rows 13..15 show the name
        call clr_rows13
        ld hl,22528+14*32      ; M2.2: rows 14..15 back to white ink (the dashboard left red label cells there)
        ld de,22528+14*32+1
        ld bc,63
        ld (hl),7
        ldir
        ld hl,name_txt
        ld de,18624+10         ; row 14, column 10
        jp print
name_txt: defb "KILL'EM ALL",0
NLEVELS equ 3
        IF DEFINED FLIP
        ELSE                   ; lane F: dropped under FLIP (dead on the 128K: shim128.asm load_level; pays for fl_* code)
LDBYTES equ 0x0556             ; ROM loader: IX = dest, DE = length, A = flag, carry = load
; load_level: A = wanted level id (1..3) -> loads 1081-byte blocks (flag 0xFF) from tape into level_data until one whose
; byte 0 is the wanted id arrives (level_data is the only RAM touched). ROM loader runs with DI; returns with EI.
load_level_tape:   ; T4 128K anchor A4 (shim load_level copies from bank 1)
        ld (ll_want),a
        call doors_restore     ; forget the door log of the level being replaced (door_n = 0): restart_level must not
                               ; write stale door codes into the freshly loaded cells
        ld hl,msg_tape
        call hud_message
        call hud_update
ll_wait:call in_scan
        jr nz,ll_wait          ; every key up (the ROM loader aborts on BREAK)
ll_try: ld ix,level_data
        ld de,1081             ; LEVEL_BLK (tools/mklevelblk.py): id + header + 1024 cells + 16 things
        ld a,0xFF
        scf
        call LDBYTES
        push af
        xor a
        out (254),a            ; border black again
        pop af
        jr nc,ll_try
        ld a,(level_data)
        ld hl,ll_want
        cp (hl)
        jr nz,ll_try
        ret
ll_want: defb 0
msg_tape: defb "LOADING NEXT LEVEL",0
        ENDIF

isr:    call snd_isr           ; T4 128K anchor A2 (AY player tick in bank 1)
        push hl
        ld hl,(ticks)
        inc hl
        ld (ticks),hl
        pop hl
        ei
        reti

cls:    ld hl,16384
        ld de,16385
        ld bc,6143
        ld (hl),0
        ldir
        ld hl,22528
        ld de,22529
        ld bc,767
        ld (hl),7
        ldir
        ret

; ---------------------------------------------------------------- level
init_game:
        call win_tint          ; M2.5: window ink for this level (TINTTAB) into the 12x24 ATTRWIN cells; render never writes attributes
        ld hl,CHJ              ; M2.5C: CHJ[n] = SCHAIN_END - 5n for n = 0..96 (sprite run-list chain entries) in RAM below BUF
        ld de,SCHAIN_END
        ld bc,5
        ld a,97
ig_chj: ld (hl),e
        inc l
        ld (hl),d
        inc l
        ex de,hl
        or a
        sbc hl,bc
        ex de,hl
        dec a
        jr nz,ig_chj
        ld hl,SOLIDPG*256      ; M2.2: solid texture page for far walls = 256 x 0xFF in RAM (idempotent, 11 B)
        ld de,SOLIDPG*256+1
        ld bc,255
        ld (hl),255
        ldir
        ld hl,level_data+1     ; skip level count; header K,1,w,h,sx,sy,angle,nthings
        ld de,4
        add hl,de
        ld a,(hl)
        ld (posx+1),a
        inc hl
        ld a,(hl)
        ld (posy+1),a
        inc hl
        ld a,(hl)
        ld (angle),a
        inc hl
        inc hl
        ld (mapptr),hl
        ld a,128
        ld (posx),a
        ld (posy),a
        jp things_init

; M2.5 win_tint: the whole 3D window has ONE ink (zero attribute clash); it is chosen per level from TINTTAB and written once
; into the window attribute cells (12 rows x 24 cells, rows 1..12 cols 4..27). Frame cells (cols 3 / 28) and the HUD stay as they are.
win_tint:
        ld hl,TINTTAB
        ld a,(level)           ; 0-based; and 3 keeps a stale value inside the 4-entry table
        and 3
        add a,l
        ld l,a
        adc a,h
        sub l
        ld h,a
        ld a,(hl)              ; ink 0..7, paper black, no bright
        ld (at_tint),a         ; M2.6 P2E: attr_write repaints the window from this tint every frame (attr.asm)
wt_fill:
        ld hl,ATTRWIN
        ld c,12
wt1:    ld b,24
wt2:    ld (hl),a
        inc l                  ; 24 cells of one row never cross a page (row low byte 0x24/0x44/../0xE4 + 23 = 0xFB)
        djnz wt2
        ld de,8                ; +32 per row: 24 done by inc l, 8 here
        add hl,de
        dec c
        jr nz,wt1
        ret
TINTTAB: defb 7,5,6,7          ; level 1 Entry white, 2 Barracks cyan, 3 Furnace yellow, (spare) white

; A = x int, C = y int -> HL = map pointer / A = cell code
cell_ptr:
        ld l,c
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        or l
        ld l,a
        ld de,(mapptr)
        add hl,de
        ret
cell_at:
        call cell_ptr
        ld a,(hl)
        ret

move_by:                       ; A = heading; moves 0.15 cell with axis-separated collision
        ld l,a
        ld h,0
        add hl,hl
        push hl
        ld de,MOVXTAB
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ld a,d
        or e
        jr z,mb1               ; M2.3: zero x delta = no x movement (no store, no floor phase step)
        ld hl,(posx)
        add hl,de
        push hl
        ld a,h
        ld hl,(posy)
        ld c,h
        call cell_at
        pop hl
        or a
        jr nz,mb1
        ld (posx),hl
        call fl_adv            ; M2.3: floor phase += B (game_a: +38 forward, -38 back = 0.15 cell)
        ld b,0                 ; once per tick: a second stored axis adds nothing
mb1:    pop hl
        ld de,MOVYTAB
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ld a,d
        or e
        ret z                  ; M2.3: zero y delta = no y movement
        ld hl,(posy)
        add hl,de
        push hl
        ld c,h
        ld a,(posx+1)
        call cell_at
        pop hl
        or a
        ret nz
        ld (posy),hl
        jp fl_adv              ; M2.3: phase += B (38 if x did not move, 0 if it did)

; print zero-terminated string HL at screen address DE (ROM font). M2.9: a loop around hud_b.asm print_char (which preserves
; HL, BC and advances DE one cell) instead of a 31 B copy of it: 9 B, same bytes on screen, pays for `steps`.
print:  ld a,(hl)
        or a
        ret z
        call print_char
        inc hl
        jr print

; ---------------------------------------------------------------- maths
; half_step: A:HL = inc (24-bit) -> C:HL = (hs_ptr 24-bit acc) + inc/2
half_step:
        sra a
        rr h
        rr l
        ld c,a
        ex de,hl
        ld hl,(hs_ptr)
        ld a,(hl)
        add a,e
        ld e,a
        inc hl
        ld a,(hl)
        adc a,d
        ld d,a
        inc hl
        ld a,(hl)
        adc a,c
        ld c,a
        ex de,hl
        ret
hs_ptr: defw accx
; ---------------------------------------------------------------- renderer
render:
        ld a,(angle)
        ld l,a
        ld h,0
        add hl,hl
        ld (angidx),hl
        ld de,COSTAB
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ld hl,(angidx)
        ld bc,PLXTAB
        add hl,bc
        ld c,(hl)
        inc hl
        ld b,(hl)
        ex de,hl
        or a
        sbc hl,bc
        ld (accx+1),hl
        xor a
        ld (accx),a
        ld l,c
        ld h,b
        ld a,h
        rla
        sbc a,a
        add hl,hl
        adc a,a
        add hl,hl
        adc a,a
        add hl,hl
        adc a,a
        ld (incx),hl
        ld (incx+2),a
        ld hl,accx
        ld (hs_ptr),hl
        ld a,(incx+2)
        ld hl,(incx)
        call half_step
        ld (accx),hl
        ld a,c
        ld (accx+2),a
        ld hl,(angidx)
        ld de,SINTAB
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ld hl,(angidx)
        ld bc,PLYTAB
        add hl,bc
        ld c,(hl)
        inc hl
        ld b,(hl)
        ex de,hl
        or a
        sbc hl,bc
        ld (accy+1),hl
        xor a
        ld (accy),a
        ld l,c
        ld h,b
        ld a,h
        rla
        sbc a,a
        add hl,hl
        adc a,a
        add hl,hl
        adc a,a
        add hl,hl
        adc a,a
        ld (incy),hl
        ld (incy+2),a
        ld hl,accy
        ld (hs_ptr),hl
        ld a,(incy+2)
        ld hl,(incy)
        call half_step
        ld (accy),hl
        ld a,c
        ld (accy+2),a
        ld a,(posy+1)
        ld c,a
        ld a,(posx+1)
        call cell_ptr
        ld (cellp),hl          ; player's cell: DDA start pointer, same for all 64 rays
        ld a,(posx)
        ld hl,ftx_cache
        cp (hl)
        jr z,rp_x
        ld (hl),a
        ld hl,FTX
        call build_ftab
rp_x:   ld a,(posy)
        ld hl,fty_cache
        cp (hl)
        jr z,rp_y
        ld (hl),a
        ld hl,FTY
        call build_ftab
rp_y:   call fl_set            ; M2.3: patch the 24 floor pushes of CLRBUF (checker / distance line) for this frame's phase
        call CLRBUF            ; back buffer: ceiling dots + mirrored lines, floor checker + lines (PUSH fill, M2.5B)
        xor a
        ld (col),a
col_loop:
        call ray
        ld a,(col)
        inc a
        ld (col),a
        cp 64
        jr c,col_loop
        call draw_things       ; T1: scaled masked sprites with zbuf depth test (M2.5: masked blit, no attributes)
        IF DEFINED FLIP
        jp fl_frame            ; lane F: COPYBUF + attr_write into the hidden screen, then request the flip (shim128.asm)
        ELSE
        call COPYBUF           ; one burst copy of the back buffer to the screen window
        jp attr_write          ; M2.6 P2E: window attributes from zbuf + sprite marks (attr.asm, ends with ret)
        ENDIF

ray:
        ld hl,(accx+1)
        ld (rdx),hl
        ld hl,(accy+1)
        ld (rdy),hl
        ld hl,(accx)
        ld de,(incx)
        add hl,de
        ld (accx),hl
        ld a,(incx+2)
        ld hl,accx+2
        adc a,(hl)
        ld (hl),a
        ld hl,(accy)
        ld de,(incy)
        add hl,de
        ld (accy),hl
        ld a,(incy+2)
        ld hl,accy+2
        adc a,(hl)
        ld (hl),a
; Y axis first: deltaY = RECIP[|rdy|], sideY = fracy*deltaY/256 (table FTY) or deltaY - that for the positive direction
        ld hl,(rdy)
        bit 7,h
        jr z,ry_pos
        xor a
        sub l
        ld l,a
        sbc a,a
        sub h
        ld h,a
        add hl,hl
        ld de,RECIP
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)              ; DE = deltay
        ld a,1
        ld (dsp),a
        ld a,d
        add a,a
        ld l,a
        ld h,FTY/256
        ld c,(hl)
        inc l
        ld b,(hl)              ; BC = fracy * dh
        ld a,e
        add a,a
        ld l,a
        ld h,FTY/256
        jr nc,$+3
        inc h
        inc l
        ld a,(hl)              ; A = (fracy * dl) >> 8
        add a,c
        ld l,a
        ld h,b
        jr nc,ry_st
        inc h
        jr ry_st
ry_pos: add hl,hl
        ld de,RECIP
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)              ; DE = deltay
        xor a
        ld (dsp),a
        ld a,d
        add a,a
        ld l,a
        ld h,FTY/256
        ld c,(hl)
        inc l
        ld b,(hl)
        ld a,e
        add a,a
        ld l,a
        ld h,FTY/256
        jr nc,$+3
        inc h
        inc l
        ld a,(hl)
        add a,c
        ld l,a
        ld h,b
        jr nc,$+3
        inc h                  ; HL = fracy * deltay / 256
        ld b,d
        ld c,e
        ex de,hl
        or a
        sbc hl,de              ; HL = deltay - fracy*deltay/256 = (1 - fracy) * deltay
        ld d,b
        ld e,c
ry_st:  push hl                ; sideY
        push de
        pop ix                 ; IX = deltaY
; X axis
        ld hl,(rdx)
        bit 7,h
        jr z,rx_pos
        xor a
        sub l
        ld l,a
        sbc a,a
        sub h
        ld h,a
        add hl,hl
        ld de,RECIP
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)              ; DE = deltax
        ld hl,dsp
        set 1,(hl)
        ld a,d
        add a,a
        ld l,a
        ld h,FTX/256
        ld c,(hl)
        inc l
        ld b,(hl)
        ld a,e
        add a,a
        ld l,a
        ld h,FTX/256
        jr nc,$+3
        inc h
        inc l
        ld a,(hl)
        add a,c
        ld l,a
        ld h,b
        jr nc,rx_st
        inc h
        jr rx_st
rx_pos: add hl,hl
        ld de,RECIP
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ld a,d
        add a,a
        ld l,a
        ld h,FTX/256
        ld c,(hl)
        inc l
        ld b,(hl)
        ld a,e
        add a,a
        ld l,a
        ld h,FTX/256
        jr nc,$+3
        inc h
        inc l
        ld a,(hl)
        add a,c
        ld l,a
        ld h,b
        jr nc,$+3
        inc h
        ld b,d
        ld c,e
        ex de,hl
        or a
        sbc hl,de
        ld d,b
        ld e,c
rx_st:  ld b,d
        ld c,e                 ; BC = deltaX, HL = sideX
        ld a,(dsp)
        add a,a
        add a,dsp_tab and 255
        ld e,a
        ld d,dsp_tab/256
        ld a,(de)
        ld (dda_call+1),a
        inc e
        ld a,(de)
        ld (dda_call+2),a
        pop de                 ; DE = sideY
        exx
        ld hl,(cellp)          ; HL' = map cell pointer for the DDA
        exx
dda_call:
        call 0
; wall height from perpendicular distance: hcol = even height 2..96, or a clipped virtual height (104..192) when perp < 1
        ld a,(side)
        cp 2
        jr nz,rh1
        xor a
        jr rh_set
rh1:    ld hl,(perp)
        call perp_h
rh_set: ld (hcol),a
        ld hl,zbuf
        ld c,a
        ld a,(col)
        add a,l
        ld l,a
        jr nc,$+3
        inc h
        ld (hl),c
        ld a,c
        cp 97
        jr c,rh4
        ld a,96                ; visible part of a clipped band
rh4:    srl a
        ld b,a
        ld a,48
        sub b
        ld (topr),a
; column geometry (M2.5C): sub4 = col & 7 (SLOTM index), bytecol = 3*(col>>3) + ADJTAB[col&7]
        ld a,(col)
        ld b,a
        and 7
        ld (sub4),a
        add a,ADJTAB and 255
        ld l,a
        ld h,ADJTAB/256
        ld a,b
        rrca
        rrca
        rrca
        and 7                  ; col >> 3 = 24-px group
        ld c,a
        add a,a
        add a,c
        add a,(hl)
        ld (bytecol),a
; M2.5: one ink for the whole window (0x07 white on black from cls, never rewritten): no per-column attributes
rd_band:
        ld a,(hcol)
        or a
        ret z
; band routine for this height, slot masks for this ray, texture page (BANDTAB, SLOTM, TEXPG share one page)
        ld h,BANDTAB/256
        ld l,a
        ld e,(hl)
        inc l
        ld d,(hl)
        ld (band_jp+1),de
        ld a,(sub4)
        add a,SLOTM and 255
        ld l,a
        ld a,(hl)              ; slot bits 192 >> 2p
        ld c,a
        cpl
        ld ixh,a               ; floor mask = not slot (kept in IXH across calc_u)
        ld a,(side)
        rrca
        sbc a,a
rd_shade:
        and 85                 ; tests poke rd_shade+1 = 0: both sides lit (walls-only geometry scan)
        cpl                    ; 255 lit side / 170 dark side
        and c
        ld ixl,a               ; texel mask = slot bits masked by the shade
        ld a,(code)
        and 15
        add a,TEXPG and 255
        ld l,a
        ld h,(hl)
        ld a,(hcol)
        cp FAR_H+1
        jr nc,$+4
        ld h,SOLIDPG           ; M2.2: far walls (<= FAR_H rows) solid ink instead of 2-3 px texel noise
        push hl                ; H = texture page
        call calc_u            ; A = u*16
        pop hl
        ld l,a                 ; HL = texture column
        ld a,(bytecol)         ; M2.5C: DE = COLBASE[bytecol] + topr (16-bit: a column may cross a page)
        add a,a
        add a,COLBASE and 255
        ld c,a
        ld b,COLBASE/256
        ld a,(bc)
        ld e,a
        inc c
        ld a,(bc)
        ld d,a
        ld a,(topr)
        add a,e
        ld e,a
        jr nc,$+3
        inc d                  ; DE = buffer address of the band's top row
        ld c,ixh               ; floor mask for rows below the horizon
band_jp:
        jp 0

; texture u (times 16) from wall hit position: frac(pos + perp * raydir) -> bits 8..15 of perp * |raydir| (|raydir| < 2:
; pl*rl >> 8, plus ph*rl, plus pl when the integer part of |raydir| is 1), added to or subtracted from the position fraction.
calc_u: ld a,(side)
        ld hl,(perp)
        or a
        jr nz,cu1
        ld de,(rdy)
        ld a,(posy)
        jr cu2
cu1:    ld de,(rdx)
        ld a,(posx)
cu2:    ex af,af'              ; A' = position fraction
        ld a,128               ; opcode add a,b
        bit 7,d
        jr z,cu3
        xor a
        sub e
        ld e,a
        sbc a,a
        sub d
        ld d,a                 ; DE = |raydir|
        ld a,144               ; opcode sub b
cu3:    ld (cu_op),a
        ld c,e                 ; C = rl (preserved by the multiplies)
        xor a
        dec d
        jr nz,cu4
        ld a,l                 ; integer part of |raydir| is 1: add pl
cu4:    ld (uacc),a
        ld a,l                 ; --- pl * rl, high byte
        ld e,a
        sub c
        jr nc,$+4
        neg
        ld b,a
        ld a,e
        add a,c
        ld l,a
        ld h,SQLO/256
        jr nc,$+3
        inc h
        ld e,(hl)
        inc h
        inc h
        ld d,(hl)
        ld l,b
        ld h,SQLO/256
        ld a,(hl)
        inc h
        inc h
        ld h,(hl)
        ld l,a
        ex de,hl
        or a
        sbc hl,de
        ld a,h
        ld hl,uacc
        add a,(hl)
        ld (hl),a
        ld a,(perp+1)          ; --- ph * rl, low byte
        ld e,a
        sub c
        jr nc,$+4
        neg
        ld b,a
        ld a,e
        add a,c
        ld l,a
        ld h,SQLO/256
        jr nc,$+3
        inc h
        ld e,(hl)
        inc h
        inc h
        ld d,(hl)
        ld l,b
        ld h,SQLO/256
        ld a,(hl)
        inc h
        inc h
        ld h,(hl)
        ld l,a
        ex de,hl
        or a
        sbc hl,de
        ld a,l
        ld hl,uacc
        add a,(hl)
        ld b,a
        ex af,af'
cu_op:  add a,b                ; or sub b
        and 240
        ret

; build_ftab: A = fraction, HL = page-aligned 512-byte table -> word [HL + 2k] = A * k for k = 0..255 (256 pushes)
build_ftab:
        ld (bf_sp+1),sp
        ld e,a
        ld d,0                 ; DE = frac
        ld a,h
        add a,2
        ld h,a
        ld sp,hl               ; SP = table end
        ld h,e
        ld l,0                 ; HL = frac * 256
        or a
        sbc hl,de              ; HL = 255 * frac
        ld b,32
bf_l:   push hl
        sbc hl,de
        push hl
        sbc hl,de
        push hl
        sbc hl,de
        push hl
        sbc hl,de
        push hl
        sbc hl,de
        push hl
        sbc hl,de
        push hl
        sbc hl,de
        push hl
        sbc hl,de
        djnz bf_l
bf_sp:  ld sp,0
        ret

; DDA exits
hit_x:  ld (code),a
        ld (perp),hl
        xor a
        ld (side),a
        ret
hit_y:  ld (code),a
        ld (perp),hl
        ld a,1
        ld (side),a
        ret
hit_far:
        xor a
        ld (code),a
        ld hl,65535
        ld (perp),hl
        ld a,2
        ld (side),a
        ret

; ---------------------------------------------------------------- variables
ticks:      defw 0
frames:     defw 0
posx:       defw 0
posy:       defw 0
angle:      defb 0
mapptr:     defw 0
angidx:     defw 0
accx:       defs 3
accy:       defs 3
incx:       defs 3
incy:       defs 3
rdx:        defw 0
rdy:        defw 0
deltax:     defw 0
deltay:     defw 0
dsp:        defb 0
perp:       defw 0
code:       defb 0
side:       defb 0
hcol:       defb 0
topr:       defb 0
col:        defb 0
sub4:       defb 0
bytecol:    defb 0
uacc:       defb 0
cellp:      defw 0
ftx_cache:  defb 1
fty_cache:  defb 1

        include "../128k/shim128.asm"   ; T4 128K anchor A3 (below 49152)
        include "gen/dda48.asm"
        include "gen/unrolled48.asm"
        include "gen/tables48.asm"
        include "../common/state.asm"
        include "../common/input.asm"
        include "../common/frontend.asm"
; T4 128K anchor A3: beeper.asm removed (AY player in bank 1 via shim128.asm)
        include "../common/game_a.asm"
        include "../common/game_b.asm"
        include "../common/game_c.asm"
        include "../common/game_d.asm"
        include "../common/game_e.asm"
        include "../common/game_f.asm"
        include "../common/game_g.asm"
        include "../common/sprites.asm"
        include "../common/sprites_b.asm"
        include "../common/sprites_c.asm"
        include "../common/sprites_d.asm"
        include "../common/sprites_e.asm"
        include "../common/sprites_f.asm"
        include "../common/hud.asm"
        include "../common/hud_b.asm"
        include "../common/attr.asm"           ; M2.6 P2E: per-frame window attribute writer
        IF DEFINED FLIP
        include "../128k/flip_hi.asm"          ; lane F (128K): fl_frame / fl_hud / fl_wait / fl_show0 (bank 0 only)
        ENDIF
; T1: gen/sprites48.asm begins with "org 27904" -> sprites, SCHAIN, NCTAB/STEPTAB/VSTEP, SPG page and level_data load low (27904..32767)
hi_end  equ $
        include "gen/sprites48.asm"
level_data:
        incbin "gen/level48.bin"   ; low block (ends below 32768; Z80-core test harnesses live in page 0x6A)
        include "../common/lowcode.asm"        ; M2.6 P2E: sprite colour marks, in the free tail of the low block (low_end <= 0x8000)
; lane G (5 Nov 2026): the 255 bytes above the IM2 vector table (TABLE 0FE00h..0FF00h, filled by start) were never used on
; either edition (bank 0 on the 128K, paged whenever game code runs): ETAB (enemy table, 128 B at 0FF70h, page-contained)
; and the enemy step code live there. The tape block now runs to 0FFEFh (the zeros it loads over the stack / TABLE area are
; rewritten by start; the image must end below 0FFFFh or pasmo's TAP length wraps). hi_end still measures the high block
; (gate: >= 40 B to the stack top 0FDF0h).
        org 0FF01h
        include "../common/etab.asm"
        org hi_end
        end start
